window.ScripturaLexicons.BDAG_PART_0006 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-angelos-bdag\" data-source=\"BDAG\" data-search=\"ἄγγελος angelos mensageiro enviado anjo mensageiro humano mensageiro Deus anjos bons maus BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἄγγελος</td><td>Substantivo</td><td>mensageiro; enviado; anjo</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-angos-bdag\" data-source=\"BDAG\" data-search=\"ἄγγος angos vaso recipiente líquidos peixe corpo espíritos BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἄγγος</td><td>Substantivo</td><td>vaso; recipiente</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-age-bdag\" data-source=\"BDAG\" data-search=\"ἄγε age vem vamos pois bem interjeição imperativo ἄγω BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἄγε</td><td>Interjeição</td><td>vem!; vamos!; pois bem!</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agele-bdag\" data-source=\"BDAG\" data-search=\"ἀγέλη agele manada rebanho porcos suínos BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἀγέλη</td><td>Substantivo</td><td>manada; rebanho</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agenealogetos-bdag\" data-source=\"BDAG\" data-search=\"ἀγενεαλόγητος agenealogetos sem genealogia Melquisedeque Hebreus BDAG\" tabindex=\"0\">\n<td class=\"table-lemma greek\">ἀγενεαλόγητος</td><td>Adjetivo</td><td>sem genealogia</td><td><span class=\"source-pill\">BDAG</span></td>\n</tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agenes-bdag\" data-source=\"BDAG\" data-search=\"ἀγενής agenes não nobre baixo insignificante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγενής</td><td>Adjetivo</td><td>não nobre; baixo; insignificante</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-agennetos-bdag\" data-source=\"BDAG\" data-search=\"ἀγέννητος agennetos não nascido não gerado ingênito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀγέννητος</td><td>Adjetivo</td><td>não nascido; não gerado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagia-pl-bdag\" data-source=\"BDAG\" data-search=\"ἅγια hagia santos santuário coisas santas veja ἅγιος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅγια</td><td>Substantivo</td><td>santuário; coisas santas (ver ἅγιος 2b)</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagiazo-bdag\" data-source=\"BDAG\" data-search=\"ἁγιάζω hagiazo consagrar dedicar santificar reverenciar purificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγιάζω</td><td>Verbo</td><td>consagrar; dedicar; santificar; reverenciar; purificar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hagiasma-bdag\" data-source=\"BDAG\" data-search=\"ἁγίασμα hagiasma santuário lugar consagrado oração templo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁγίασμα</td><td>Substantivo</td><td>santuário; lugar consagrado</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-angelos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἄγγελος</h1>\n<div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ángelos⟧</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> (Hom.+.) “<strong>Mensageiro</strong>”.\n<span class=\"sense-number\">1.</span>\n<strong>Mensageiro humano que serve como enviado, emissário, alguém enviado.</strong>\n<strong>a.</strong> Por seres humanos (Hom.+; inscrições, papiros;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.32.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 32.4</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.32.7\" target=\"_blank\" rel=\"noopener noreferrer\">7</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jt 1.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">3.1</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.1.44\" target=\"_blank\" rel=\"noopener noreferrer\">1Mc 1.44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">7.10</a>; Jos., <em>Ant.</em> 14, 451; <em>Vi.</em> 89): no ministério terreno de Jesus,\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπέστειλεν ἀγγέλους\" data-meanings=\"enviou mensageiros\">ἀπέστειλεν ἀγγέλους</span> (Diod S 2, 18, 1: o rei da Índia a Semíramis; 4, 65, 4),\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.52</a>; dos discípulos de João Batista, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">7.24</a>; dos exploradores de Josué, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 2.25</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOS.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Js 7.22</a>).\n<strong>b.</strong> Por Deus: profetas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/HAG.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ag 1.13</a>; subscrição de Malaquias; sacerdote, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/MAL.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ml 2.7</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.1.48\" target=\"_blank\" rel=\"noopener noreferrer\">1 Esd 1.48 s.</a>. Compare também Theognis 1, 769, em que o poeta é\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Μουσέων ἄγγελος\" data-meanings=\"mensageiro das Musas\">Μουσέων ἄγγελος</span>; Epict. 3, 22, 23; 38; Ael. Aristid. 37 K.=1 p. 15 D.; Maximus Tyr. 11, 9c: Platão, como aquele que nos traz informação sobre Deus, é chamado <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἐξ Ἀκαδημίας ἄγγ.\" data-meanings=\"o mensageiro vindo da Academia\">ὁ ἐξ Ἀκαδημίας ἄγγ.</span>; Oenomaus em Eus., <em>PE</em> 5, 20, 3; 5: Carnus, o adivinho, é <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγγ.\" data-meanings=\"mensageiro\">ἄγγ.</span> dos deuses. De João Batista como precursor:\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11.10</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.2</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.27</a> (todos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/MAL.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ml 3.1</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.23.20\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 23.20</a>).\n<span class=\"sense-number\">2.</span>\n<strong>Poder transcendente que executa diversas missões ou tarefas, mensageiro, anjo.</strong> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"ἄγγελος; mensageiro, anjo\">ἄ.</span> como ser espiritual, frequentemente relacionado ao mundo inferior em fontes greco-romanas: E. Ziebarth, “Neue attische Fluchtafeln”, NGG 1899, 127 ss. nº 24; IG XII/3, 933–974; outros materiais em Dibelius, <em>Geisterwelt</em> 209 ss.; também os oráculos: <em>Theosophien</em> 13 p. 169, 31; Ps.-Callisth. 1, 1, 3 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπεκαλεῖτο τοὺς ἀγγέλους καὶ θεὸν Ἄμμωνα\" data-meanings=\"invocava os anjos e o deus Amon\">ἐπεκαλεῖτο τοὺς ἀγγέλους καὶ θεὸν Ἄμμωνα</span>; 2, 25, 1; Porphyr., <em>Ad Marcellam</em> 21\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγγελοι θεῖοί τε κ. ἀγαθοὶ δαίμονες\" data-meanings=\"anjos divinos e bons espíritos\">ἄγγελοι θεῖοί τε κ. ἀγαθοὶ δαίμονες</span>; Hierocles 3, 424; 23, 468;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"anjos\">ἄ.</span> com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θεοί\" data-meanings=\"deuses\">θεοί</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δαίμονες\" data-meanings=\"espíritos; daimones\">δαίμονες</span> em Damascius 183 Ruelle;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"anjos\">ἄ.</span> com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δαίμονες\" data-meanings=\"espíritos; daimones\">δαίμονες</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἥρωες\" data-meanings=\"heróis\">ἥρωες</span> em Proclus, <em>Rep.</em> II 243 Kroll, <em>Tim.</em> III 109 Diehl. — F. Cumont, RHR 72, 1915, 159–182; F. Andres, <em>D. Engellehre d. griech. Apologeten</em> 1914 e Pauly-W. Suppl. III 1918, 101 ss.; Rtzst., <em>Myst.</em> 171, 2; Bousset, ARW 18, 1915, 170 ss.) e como poder transcendente no judaísmo (LXX; En 10:7; 20:1; 99:3 e outros; essênios em Jos., <em>Bell.</em> 2, 142; Fílon, compare Schürer III 881–885, com bibliografia; Josefo; Test12Patr; orações de vingança de Reneia [séc. I a.C.] 9 s.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κύριε ὁ πάντα ἐφορῶν καὶ οἱ ἄνγελοι θεοῦ\" data-meanings=\"Senhor que tudo vês, e os anjos de Deus\">κύριε ὁ πάντα ἐφορῶν καὶ οἱ ἄνγελοι θεοῦ</span>; sobre isso Dssm. LO 353 s.; 357 = LAE 414; 418 s.; SIG 1181, nota 2; PFouad 203, 3 s. [séc. I d.C.]; sobre isso P. Benoit, RB 58, 1951, 549–565; P. Katz, TZ 10, 1954, 228–231. Palavra de empréstimo no rabínico. — Bousset, <em>Rel.</em> 320 ss.; J.-B. Frey, “L’Angélologie juive au temps de J-Chr.”, RSPT 5, 1911, 75–110; H. Kuhn, JBL 67, 1948, 217–232, sobre apocalipses judaicos), igualmente nos papiros mágicos, com sua mistura de influências gentílicas e judaicas (PGM 1, 76: um <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"anjo\">ἄ.</span> como estrela do céu; 4, 570 ss.; 998; 1112; 13, 329; 585; 609; 744). Compare a inscrição APF 3, 1906, 445 nº 67; 451 nº 94. O termo mais comum na literatura politeísta para seres intermediários entre deuses e seres humanos é\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δαίμων\" data-meanings=\"daímon; ser espiritual intermediário\">δαίμων</span> [q.v.], que escritores monoteístas reservaram para um domínio hostil aos interesses de Deus, conservando <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"ἄγγελος; anjo\">ἄ.</span> para seres intermediários, leais a Deus ou em rebelião.\n<strong>a.</strong> <strong>Como mensageiros de Deus, anjos.</strong> (LXX; Fílon, <em>Somn.</em> 1, 190; mensageiros transcendentes dos deuses em Homero não são seres intermediários; porém a descrição de Hermes, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κῆρυξ τῶν θεῶν\" data-meanings=\"arauto dos deuses\">κῆρυξ τῶν θεῶν</span>, como seu <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγγελος ἄριστος\" data-meanings=\"excelentíssimo mensageiro\">ἄγγελος ἄριστος</span> [Diod S 5, 75, 2] pode ter facilitado aos greco-romanos compreender\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"anjo; mensageiro\">ἄ.</span> como mensageiro celeste de Deus; compare o mensageiro do deus Men: EA 18, 1891 p. 92 s., nº 2, 5 s.) principalmente com genitivo:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κυρίου\" data-meanings=\"do Senhor\">κυρίου</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 16.10 s.</a> e outros)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1.20</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2.13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">19</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.11</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2.9</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.19</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">12.7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῦ θεοῦ\" data-meanings=\"de Deus\">τοῦ θεοῦ</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.31.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 31.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.32.2\" target=\"_blank\" rel=\"noopener noreferrer\">32.2</a> e outros; Fílon, <em>Deus Imm.</em> 1; Jos., <em>Bell.</em> 5, 388)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.8 s.</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">15.10</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.51</a> (H. Windisch, ZNW 30, 1931, 215–233; veja também abaixo sobre Lc 2.15).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. θεοῦ\" data-meanings=\"anjo de Deus\">ἄ. θεοῦ</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.21.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 21.17</a> A; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDG.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jz 13.6</a> B; Jos., <em>Ant.</em> 1, 73; Orig., <em>C. Cels.</em> 8, 31, 18)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 4.14</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.6</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.96.7\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 96.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.32.43\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 32.43</a>); 1 Cl 29:2 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.32.8\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 32.8</a>). Absolutamente (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.20.16\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 20.16</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDG.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Jz 13.11</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 6.4 ss.</a> e outros):\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">18</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">38</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2.10</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">15</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">21</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20.12</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.53\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.53</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 3.16</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 1.12</a> (num jogo de palavras sobre a superioridade dos seres humanos aos anjos, veja Sextus 32; sobre seu estatuto e classificação, veja também Orig., <em>C. Cels.</em> 4, 29, 16), entre outros.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιοι ἄ.\" data-meanings=\"anjos santos\">ἅγιοι ἄ.</span> (PGM 4, 1934, 1938)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.38</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.26</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.22</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.10</a>; 1 Cl 39:7 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 5.1</a>); Hv 2, 2, 7.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐκλεκτοὶ ἄ.\" data-meanings=\"anjos eleitos\">ἐκλεκτοὶ ἄ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 5.21</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"anjos\">ἄ.</span> como testemunhas também TestLevi 19:3 e SIG 1181, 10 = Dssm. LO 351–362 [LAE 413–424]; compare Jos., <em>Bell.</em> 2, 401);\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. ἰσχυρός\" data-meanings=\"anjo forte\">ἄ. ἰσχυρός</span> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DAN.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">Dn 4.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.102.20\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 102.20</a>)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.21\" target=\"_blank\" rel=\"noopener noreferrer\">18.21</a>. Sua morada é o céu, e por isso são\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. τῶν οὐρανῶν\" data-meanings=\"anjos dos céus\">ἄ. τῶν οὐρανῶν</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.36</a> (a menos que <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐρ.\" data-meanings=\"céus\">οὐρ.</span> = <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θεοῦ\" data-meanings=\"de Deus\">θεοῦ</span>);\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. ἐν τοῖς οὐρανοῖς\" data-meanings=\"anjos nos céus\">ἄ. ἐν τοῖς οὐρανοῖς</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.25</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. ἐν οὐρανῷ\" data-meanings=\"anjos no céu\">ἄ. ἐν οὐρανῷ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.32\" target=\"_blank\" rel=\"noopener noreferrer\">13.32</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. ἐξ οὐρανοῦ\" data-meanings=\"anjo vindo do céu\">ἄ. ἐξ οὐρανοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.8</a>, compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">28.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.43\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.43</a>. Retornam ao céu quando cumprem sua missão na terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.15</a>. Daí <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. φωτός\" data-meanings=\"anjo de luz\">ἄ. φωτός</span> (compare SJCh 78, 17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 11.14</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. φωταγωγοί\" data-meanings=\"anjos portadores de luz\">ἄ. φωταγωγοί</span> <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 18:1\" data-tooltip-text=\"Epístola de Barnabé 18:1\">B 18:1</span>. Ali os bons se unem a eles após a morte, Hv 2, 2, 7; Hs 9, 27, 3. Aparecem em luz deslumbrante,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2.9</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.30</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 3.2</a>); ISm 6:1; compare a “face brilhante” de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 6.15</a>; ou em vestes brancas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20.12</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.4</a>. Chamados <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεύματα\" data-meanings=\"espíritos\">πνεύματα</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.7</a>; 1 Cl 36:3 (ambos após <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.103.4\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 103.4</a>).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πνεύματα λειτουργικά\" data-meanings=\"espíritos ministradores\">πνεύματα λειτουργικά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.14</a>. Sua voz é como trovão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12.29</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γλῶσσαι τῶν ἀ.\" data-meanings=\"línguas dos anjos\">γλῶσσαι τῶν ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 13.1</a> (por analogia com as linguagens dos deuses, Platão em Clem. Al., <em>Strom.</em> 1, 143; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 12.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.2 s.</a>; TestJob 48–50; G. Steindorff, <em>Apk. d. Elias</em>: TU 17, 3a, 1899, 153). Trazem mensagens de Deus aos seres humanos,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.11 s.</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.2 ss.</a>, e também atuaram na entrega da lei:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"νόμος διαταγεὶς δι’ ἀγγέλων\" data-meanings=\"lei promulgada por meio de anjos\">νόμος διαταγεὶς δι’ ἀγγέλων</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 3.19</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.38\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.38</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.53\" target=\"_blank\" rel=\"noopener noreferrer\">53</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.2</a> (Jos., <em>Ant.</em> 15, 136 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῶν ἐν τοῖς νόμοις δι’ ἀγγέλων παρὰ τ. θεοῦ μαθόντων\" data-meanings=\"dos que aprenderam de Deus as coisas da lei por meio de anjos\">τῶν ἐν τοῖς νόμοις δι’ ἀγγέλων παρὰ τ. θεοῦ μαθόντων</span>; compare Did., <em>Gen.</em> 110, 15\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κἂν γὰρ διὰ ὑπουργῶν ἀγγέλων ποιῇ ἃ βούλεται θεός\" data-meanings=\"ainda que Deus faça por meio de anjos servidores aquilo que quer\">κἂν γὰρ διὰ ὑπουργῶν ἀγγέλων ποιῇ ἃ βούλεται θεός</span>). Como anjos da guarda de indivíduos (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 5.6</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">22</a>; compare PGM 1, 172 ss.; Ael. Aristid. 50, 57 K.=26 p. 519 D.:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ σὸς Ἑρμῆς ἐστιν\" data-meanings=\"é o teu Hermes\">ὁ σὸς Ἑρμῆς ἐστιν</span>, a quem Aristides fora confiado desde o nascimento),\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18.10</a> (P. Barry, ET 23, 1912, 182);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.15</a> (J. Moulton, JTS 3, 1902, 514–527; ET 14, 1903, 5 ss.);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4.10</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.90.11\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 90.11</a>); Hv 5:1 s. Conduzem os mortos bem-aventurados ao céu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.22</a> (Hermes o faz segundo os pitagóricos [Diog. L. 8, 31]); instruem os seres humanos a fazer o bem, Hv 3, 5, 4;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δικαιοσύνης\" data-meanings=\"de justiça\">δικαιοσύνης</span> <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"m 6, 2, 1\" data-tooltip-text=\"Pastor de Hermas, Mandamentos 6, 2, 1\">m 6, 2, 1</span> (ParJer 8:12); alegram-se com o arrependimento do pecador, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.10</a>; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. τῆς μετανοίας\" data-meanings=\"anjo do arrependimento\">ἄ. τῆς μετανοίας</span> Hm 12, 4, 7; 12, 6, 1 e outros. Presidem a vários domínios:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. ὁ ἔχων ἐξουσίαν ἐπὶ τοῦ πυρός\" data-meanings=\"anjo que tem autoridade sobre o fogo\">ἄ. ὁ ἔχων ἐξουσίαν ἐπὶ τοῦ πυρός</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14.18</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. τῶν ὑδάτων\" data-meanings=\"anjo das águas\">ἄ. τῶν ὑδάτων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">16.5</a>; os quatro ventos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">7.1</a>. Deus lhes atribui <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"διακόσμησις γῆς\" data-meanings=\"ordenação da terra\">διακόσμησις γῆς</span> Pa (4) (compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγγελοι ἐπὶ τῶν ἐξουσιῶν\" data-meanings=\"anjos sobre os poderes\">ἄγγελοι ἐπὶ τῶν ἐξουσιῶν</span> GrBar 12:3). Um anjo, Thegri, governa o mundo animal, Hv 4, 2, 4 (Synes., <em>Ep.</em> 57 p. 192b: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δαίμονες\" data-meanings=\"daimones; espíritos\">δαίμονες</span> como chefes dos gafanhotos).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. τοῦ πνεύματος τοῦ προφητικοῦ\" data-meanings=\"anjo do espírito profético\">ἄ. τοῦ πνεύματος τοῦ προφητικοῦ</span> Hm 11:9;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν ἄ. τὸν τιμωρητήν\" data-meanings=\"o anjo punidor\">τὸν ἄ. τὸν τιμωρητήν</span> Hs 7:6; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἄ. ὁ μέγας\" data-meanings=\"o grande anjo\">ὁ ἄ. ὁ μέγας</span> Hs 8, 4, 1. — Como criador do mundo, AcPlCor 1:15. Sobre <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. τῶν ἐκκλησιῶν\" data-meanings=\"anjos das igrejas\">ἄ. τῶν ἐκκλησιῶν</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 1.20</a>, compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">8</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">12</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">18</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">3.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">7</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">14</a> (sobre os problemas textuais associados a esses versículos, veja R. Charles, <em>ICC Comm.</em> 1920, I, clvii; clxf; II 244; R. Borger, TRu 52, 1987, 42 s.) e veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀστήρ\" data-meanings=\"estrela\">ἀστήρ</span>. Subordinados a Cristo:\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.11</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">13.41</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">16.27</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1.4 ss.</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.96.7\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 96.7</a>; B-D-F §254, 2);\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 3.22</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5.11 s.</a>; glorificam-no, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.51\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1.51</a> (J. Fritsch, “… videbitis … angelos Dei ascendentes …”, VD 37, 1959, 1–11).\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δώδεκα λεγιῶνας ἀ.\" data-meanings=\"doze legiões de anjos\">δώδεκα λεγιῶνας ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.53\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26.53</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μυριάσιν ἀ.\" data-meanings=\"miríades de anjos\">μυριάσιν ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.22\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12.22</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 5.11</a>. Sete anjos principais (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 12.15</a>)\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 8.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">6</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.1\" target=\"_blank\" rel=\"noopener noreferrer\">15.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">6</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">16.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.1\" target=\"_blank\" rel=\"noopener noreferrer\">17.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">21.9</a> (G. Dix, “The Seven Archangels and the Seven Spirits”, JTS 28, 1927, 233–250). Seis anjos, criados primeiro, aos quais é confiada a administração de toda a criação, Hv 3, 4, 1. Anjos na Parúsia:\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24.31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ts 1.7</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Μιχαὴλ καὶ οἱ ἄ. αὐτοῦ\" data-meanings=\"Miguel e os seus anjos\">Μιχαὴλ καὶ οἱ ἄ. αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12.7</a>. Reverenciados por pessoas (Celsus 1, 26: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἰουδαίους σέβειν ἀγγέλους\" data-meanings=\"os judeus reverenciam anjos\">Ἰουδαίους σέβειν ἀγγέλους</span>; 5, 6):\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θρησκείᾳ τῶν ἀ.\" data-meanings=\"culto de anjos\">θρησκείᾳ τῶν ἀ.</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2.18</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λατρεύειν ἀγγέλοις\" data-meanings=\"prestar culto a anjos\">λατρεύειν ἀγγέλοις</span> como sinal de piedade judaica, PtK 2 p. 14, 26 = Clem. Al., <em>Strom.</em> 6, 41 p. 452, 9. Cristo como <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σεμνότατος ἄ.\" data-meanings=\"o mais venerável anjo\">σεμνότατος ἄ.</span> Hv 5:2; Hm 5, 1, 7; compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἅγιος ἄ.\" data-meanings=\"o santo anjo\">ὁ ἅγιος ἄ.</span> Hs 5, 4, 4 v.l.;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἔνδοξος ἄ.\" data-meanings=\"o glorioso anjo\">ὁ ἔνδοξος ἄ.</span> Hs 5, 4, 4; 7:1 ss.; 8, 1, 2.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἄ. κυρίου\" data-meanings=\"o anjo do Senhor\">ὁ ἄ. κυρίου</span> Hs 7:5; 8, 1, 2 ss.; chamado Miguel em Hs 8, 3, 3, onde se deve notar que Miguel era o anjo guardião do povo de Deus (W. Lueken, <em>D. Erzengel Michael</em> 1900; M. Dibelius, <em>Hdb.</em>, exc. sobre Hs 5, 6, 8 p. 575 s.).\n<strong>b.</strong> <strong>Seres intermediários em geral, sem referência à relação deles com Deus</strong> (opostos a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄνθρωποι\" data-meanings=\"seres humanos\">ἄνθρωποι</span>; veja 2 imediatamente antes de a):\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 4.9</a> (compare TestJos 19:9\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἔχαιρον ἐπ’ αὐτῷ οἱ ἄγγελοι κ. οἱ ἄνθρωποι κ. πᾶσα ἡ γῆ\" data-meanings=\"alegravam-se por ele os anjos, os seres humanos e toda a terra\">ἔχαιρον ἐπ’ αὐτῷ οἱ ἄγγελοι κ. οἱ ἄνθρωποι κ. πᾶσα ἡ γῆ</span>). — <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.8.38\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 8.38</a>:\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ.\" data-meanings=\"anjos\">ἄ.</span> como potências espirituais servidoras parecem distinguir-se das\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀρχαί\" data-meanings=\"principados; poderes governantes\">ἀρχαί</span>, que governam.\n<strong>c.</strong> <strong>Espíritos maus.</strong> (Lactant., <em>Inst.</em> 2, 15, 8:\n<em>daemonas Trismegistus angelos poneros appellat</em>. Compare também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jó 1.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOB.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2.1</a>; Fílon, <em>Gig.</em> 16; TestAsh 6:4; PGM 4, 2701;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"αἱ πονηραὶ δυνάμεις, διάβολος καὶ οἱ ἄγγελοι αὐτοῦ\" data-meanings=\"as potências malignas, o diabo e seus anjos\">αἱ πονηραὶ δυνάμεις, διάβολος καὶ οἱ ἄγγελοι αὐτοῦ</span> Did., <em>Gen.</em> 45, 5.)\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τῷ διαβόλῳ καὶ τοῖς ἀγγέλοις αὐτοῦ\" data-meanings=\"ao diabo e aos seus anjos\">τῷ διαβόλῳ καὶ τοῖς ἀγγέλοις αὐτοῦ</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25.41</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 12.9</a>.\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ δράκων καὶ οἱ ἄ. αὐτοῦ\" data-meanings=\"o dragão e os seus anjos\">ὁ δράκων καὶ οἱ ἄ. αὐτοῦ</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">v. 7</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. τῆς ἀβύσσου\" data-meanings=\"anjo do abismo\">ἄ. τῆς ἀβύσσου</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">9.11</a> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἀβαδδών\" data-meanings=\"Abadom\">Ἀβαδδών</span>);\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. πονηρός\" data-meanings=\"anjo mau\">ἄ. πονηρός</span> <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 9:4\" data-tooltip-text=\"Epístola de Barnabé 9:4\">B 9:4</span>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. τῆς πονηρίας\" data-meanings=\"anjo da maldade\">ἄ. τῆς πονηρίας</span> em contraste com anjos da guarda, Hm 6, 2, 1;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. Σατανᾶ\" data-meanings=\"anjo de Satanás\">ἄ. Σατανᾶ</span>, que causa dor física,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Co 12.7</a>; especialmente chamado\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. τρυφῆς καὶ ἀπάτης\" data-meanings=\"anjo do luxo e do engano\">ἄ. τρυφῆς καὶ ἀπάτης</span> Hs 6, 2, 1 s.; conduzindo seres humanos ao mal, <span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 18:1\" data-tooltip-text=\"Epístola de Barnabé 18:1\">B 18:1</span>. Da queda dos anjos e de seu castigo (compare, na opinião de muitos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 6.2</a>; En 6 ss.; 54; Livro dos Jubileus 5; SyrBar 56:13; L. Jung, <em>Fallen Angels in Jewish, Christian, and Mohammedan Lit.</em> 1926; A. Lods, <em>Congr. d’Hist. du Christ.</em> I 29–54):\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ θεὸς ἀγγέλων ἁμαρτησάντων οὐκ ἐφείσατο\" data-meanings=\"Deus não poupou anjos quando pecaram\">ὁ θεὸς ἀγγέλων ἁμαρτησάντων οὐκ ἐφείσατο</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pe 2.4</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ. τοὺς μὴ τηρήσαντας τὴν ἑαυτῶν ἀρχήν\" data-meanings=\"anjos que não conservaram o seu próprio domínio\">ἀ. τοὺς μὴ τηρήσαντας τὴν ἑαυτῶν ἀρχήν</span>, “que não conservaram seu domínio próprio” (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀρχή\" data-meanings=\"domínio; esfera de autoridade\">ἀρχή</span> 7),\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 6</a>. Da passagem já citada com <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 6.2</a> (compare também TestReub 5:3; Jos., <em>Ant.</em> 1, 73 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγγελοι θεοῦ γυναιξὶ συνιόντες\" data-meanings=\"anjos de Deus unindo-se a mulheres\">ἄγγελοι θεοῦ γυναιξὶ συνιόντες</span>; e o conceito politeísta de desejos eróticos de seres transcendentes: H. Usener, <em>Weihnachtsfest</em><sup>2</sup> 1911, 74 s.; Rtzst., <em>Poim.</em> 228 ss., <em>Herr der Grösse</em> 14 s.; e GJs 14:1), alguns concluem que os anjos estavam sujeitos a desejos eróticos; sustenta-se que isso explique a regra de que mulheres usem véu nos cultos, pois os anjos estão presentes (compare Orig., <em>Orat.</em> 31 e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.137.1\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 137.1</a>\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐναντίον ἀγγέλων ψαλῶ σοι\" data-meanings=\"diante dos anjos cantarei a ti\">ἐναντίον ἀγγέλων ψαλῶ σοι</span>),\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 11.10</a> (para outra interpretação e bibliografia, veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐξουσία\" data-meanings=\"autoridade; direito\">ἐξουσία</span> 7; veja também J. Fitzmyer, sobre angelologia de Qumran, NTS 4, 1957/58, 48–58; L. Jervis, JBL 112, 1993, 243–245: os anjos mediam a presença de Deus). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 6.3</a>,\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ οἴδατε, ὅτι ἀγγέλους κρινοῦμεν;\" data-meanings=\"não sabeis que julgaremos anjos?\">οὐκ οἴδατε, ὅτι ἀγγέλους κρινοῦμεν;</span>, não é certo se apenas anjos caídos são designados;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θρησκείᾳ τῶν ἀ.\" data-meanings=\"culto de anjos\">θρησκείᾳ τῶν ἀ.</span>\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 2.18</a> polemiza contra o que parece ser um tipo de reverência gnóstica por anjos. (Sobre angelologia de Qumran, veja Fitzmyer, citado acima.) — O. Everling, <em>D. paulinische Angelologie u. Dämonologie</em> 1888; Dibelius, <em>Geisterwelt</em> 1909; G. Kurze, <em>D. Engels-u. Teufels-glaube d. Ap. Pls</em> 1915; M. Jones, “St Paul and the Angels”, <em>Exp.</em>, 8ª sér., 16, 1921, 356–370; 412–425; E. Peterson, <em>D. Buch von den Engeln</em> 1935; J. Michl, <em>D. Engelvorstellungen in Apk</em> I 1937; E. Langton, <em>The Angel Teaching of the NT</em> 1937; J. Bernardin, JBL 57, 1938, 273–279; E. Schick, <em>D. Botschaft der Engel im NT</em> 1940; W. Michaelis, <em>Z. Engelchristol. im Urchristent.</em> 1942; G. Hatzidakis, “Ἄγγελος u. Verwandtes”, SBWienAk 173, 1914. — B. 1486. DELG. DDD 81–96 (bibliografia). M-M. <em>New Docs</em> 5, 72 s. TW. Sv.\n</p>\n</section>\n</article><article id=\"entry-angos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἄγγος</h1>\n<div class=\"entry-meta\"><span class=\"greek\">ους, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦ángos⟧</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> (Hom. e outros; CIG 3573; Michel 1361, 5; LXX; Fílon, <em>Post. Cai.</em> 130; Jos., <em>Ant.</em> 8, 322.)\n<strong>Recipiente principalmente para líquidos ou objetos úmidos, vaso, recipiente</strong>,\n<span class=\"biblio-ref tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"biblio\" data-tooltip-label=\"B 8:1\" data-tooltip-text=\"Epístola de Barnabé 8:1\">B 8:1</span>. De recipientes para peixe,\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.48</a> (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγγεῖα\" data-meanings=\"recipientes; forma variante\">ἀγγεῖα</span>, q.v.). Figuradamente, do corpo como morada de espíritos maus, Hm 5, 2, 5 (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγγεῖον\" data-meanings=\"vaso; recipiente\">ἀγγεῖον</span>). Sobre a v.l., veja G. Kilpatrick, “Style and Text in the Gk. NT”,\n<em>Studies and Docs.</em> 29, 1967, 156. — DELG. M-M, s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγγεῖον\" data-meanings=\"vaso; recipiente\">ἀγγεῖον</span>.\n</p>\n</section>\n</article><article id=\"entry-age-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἄγε</h1>\n<div class=\"entry-meta\"><span class=\"transliteration\">⟦áge⟧</span><span class=\"separator\">·</span><span>interjeição</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> Imperativo presente de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγω\" data-meanings=\"conduzir; levar; ir\">ἄγω</span>, usado como interjeição (desde Homero, com singular ou plural; LXX; SibOr 3, 562; B-D-F §144;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγε μέν\" data-meanings=\"vamos, pois; ora então\">ἄγε μέν</span>):\n<strong>vem! vamos!</strong>\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄγε νῦν\" data-meanings=\"vamos agora; pois bem\">ἄγε νῦν</span> (especialmente frequente na comédia), seguido de imperativo (Hom.),\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.1</a>; seguido de anacoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">4.13</a>;\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄ. δή\" data-meanings=\"vem então; pois bem\">ἄ. δή</span> (Ésquilo e outros), <strong>vem então!</strong>, Dg 2:1.\n</p>\n</section>\n</article><article id=\"entry-agele-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἀγέλη</h1>\n<div class=\"entry-meta\"><span class=\"greek\">ης, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agélē⟧</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"> (Hom. e outros.)\n<strong>Manada de porcos</strong> (Hes., <em>Scutum</em> 168; Eudoxus Rhod. [séc. II a.C.] em Aelian, <em>NA</em> 10, 16):\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8.30–32</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.11</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">13</a>;\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.32 s.</a>. — DELG. M-M.\n</p>\n</section>\n</article><article id=\"entry-agenealogetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\">\n<div><h1 class=\"entry-title greek\">ἀγενεαλόγητος</h1>\n<div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agenealógētos⟧</span></div>\n</div><div class=\"source-tag\">BDAG</div>\n</header>\n<div class=\"entry-divider\"></div>\n<section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">\n<strong>Sem genealogia</strong>, de Melquisedeque (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπάτωρ\" data-meanings=\"sem pai\">ἀπάτωρ</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀμήτωρ\" data-meanings=\"sem mãe\">ἀμήτωρ</span>),\n<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7.3</a> (encontrado em outros lugares somente com referência a essa passagem). — M-M.\n</p>\n</section>\n</article><article id=\"entry-agenes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγενής</h1><div class=\"entry-meta\"><span class=\"greek\">ές · gen. οῦς</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agenḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<strong>Não de nascimento nobre</strong> (<em>ignobilis</em>; oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐγενής\" data-meanings=\"de nascimento nobre\">εὐγενής</span>; neste sentido desde Xenofonte e Platão; POxy 33 V, 5 [séc. II d.C.] = <em>Acta Alex.</em> XI, B col. V, 5; Jos., <em>Bell.</em> 4, 148; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγεννής\" data-meanings=\"forma variante citada pelo BDAG\">ἀγεννής</span> Just. <em>A</em> II, 3, 3), mas também no sentido mais geral <strong>baixo, vil, insignificante</strong> (Sófocles, <em>Fgm.</em> 84 Pears., oposto a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγαθός\" data-meanings=\"bom; nobre\">ἀγαθός</span>; Fílon, <em>Conf. Lingu.</em> 43; POxy 79, 3; SIG² 855, 11; 862, 22), que é muito provavelmente o sentido em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 1.28</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γίγνομαι\" data-meanings=\"vir a ser; nascer\">γίγνομαι</span> 223. M-M.\n</p></section>\n</article><article id=\"entry-agennetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀγέννητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦agénnētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"> (Sófocles e outros.) <strong>Relativo a quem existe sem ter passado pelo processo de nascer, não nascido</strong>, literalmente <strong>“não gerado”</strong> (assim de Deus, Herm. Wr. 2, 4; 5, 2; 14, 2 e outros; TestSol; ParJer 9:6; Fílon, <em>Mos.</em> 2, 171 v.l. [por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγένητος\" data-meanings=\"não gerado; variante gráfica citada\">ἀγένητος</span>]; Justino. Escrito <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγένητος\" data-meanings=\"não gerado; grafia citada pela fonte\">ἀγένητος</span>: Tales, Fgm. A 1, 35 = Diog. L. 1, 35; Zoroastro em Fílon de Biblos [c. 100 d.C.]: 790 Fgm. 4, 52 Jac. [Eus., <em>PE</em> 1, 10, 52]; PGM 13, 842; Fílon; Jos., <em>C. Ap.</em> 2, 167; SibOr, Fgm. 1, 7; 17; Ath. [<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγένν.\" data-meanings=\"abreviação de ἀγέννητος\">ἀγένν.</span> — códice A]; Theoph. Ant. 1, 4, p. 64, 3), com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γεννητός\" data-meanings=\"gerado\">γεννητός</span>, de Cristo (compare AcPh 141 [Aa II/2, 76, 27]) IEph 7:2 (v.l. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγένητος\" data-meanings=\"não gerado\">ἀγένητος</span>); compare Lghtf., <em>Apost. Fath.</em> II/2², 1889, pp. 90–94. Este termo deve ser restaurado em Ox 1081, 34: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγ[εννή]του π̄ρ̄ς̄\" data-meanings=\"do Pai não gerado\">ἀγ[εννή]του π̄ρ̄ς̄</span>, “Pai não gerado”; semelhantemente na linha 48 (ambos com base no texto copta <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγένητο\" data-meanings=\"forma copta/grega citada pela fonte\">ἀγένητο</span> SJCh 90, 12; 91, 13). — P. Stiegele, <em>D. Agennesiebegriff in d. griech. Theol. d. 4 Jh.</em> 1913; L. Prestige, JTS 24, 1923, 486–496; J. Lebreton, “Ἀγέννητος dans la Tradition philos. et dans la Litt. chrét. du IIe siècle”, RSR 16, 1926, 431–443; G. Delling, <em>Jüd. Lehre u. Frömmigkeit</em>, Berlin 1967, 36 ss. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γίγνομαι\" data-meanings=\"vir a ser; nascer\">γίγνομαι</span> 223. Sv.\n</p></section>\n</article><article id=\"entry-hagia-pl-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅγια</h1><div class=\"entry-meta\"><span class=\"greek\">ων</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hágia⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅγιος\" data-meanings=\"santo; sagrado\">ἅγιος</span> 2b.</p></section>\n</article><article id=\"entry-hagiazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγιάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hagiázō⟧</span><span class=\"separator\">·</span><span class=\"greek\">1 aor. ἡγίασα; impv. ἁγίασον; pf. ἡγίακα · pass. fut. ἁγιασθήσομαι; 1 aor. ἡγιάσθην; impv. ἁγιασθήτω; pf. ἡγίασμαι; ptc. ἡγιασμένος</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\">\n<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡγίακα\" data-meanings=\"perfeito de ἁγιάζω\">ἡγίακα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/2CH.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cr 7.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JER.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jr 1.5</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡγιασμένος\" data-meanings=\"santificado; consagrado\">ἡγιασμένος</span> 1 Cl 46:2. (LXX; Fílon, <em>Leg. All.</em> 1, 18; <em>Spec. Leg.</em> 1, 67. Bastante raro fora do uso bíblico, onde <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγίζω\" data-meanings=\"purificar; consagrar\">ἁγίζω</span> é a forma usual; mas veja PGM 4, 522 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιασθείς\" data-meanings=\"tendo sido santificado\">ἁγιασθείς</span>; Cat. Cod. Astr. VII 178, 1; 27; <em>Anecd. Gr.</em> p. 328, 1 ss. e Herm. Wr. 1, 32 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"συναγιάζειν\" data-meanings=\"santificar juntamente\">συναγιάζειν</span>. Compare também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καθαγιάζειν\" data-meanings=\"consagrar; santificar\">καθαγιάζειν</span> sob 3 abaixo.)\n<span class=\"sense-number\">1.</span> <strong>Separar algo ou torná-lo apropriado para fins rituais, consagrar, dedicar</strong>, de coisas: (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.29.27\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 29.27</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.29.37\" target=\"_blank\" rel=\"noopener noreferrer\">37</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.29.44\" target=\"_blank\" rel=\"noopener noreferrer\">44</a> e outros) <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. τὸ δῶρον\" data-meanings=\"consagrar a oferta\">ἁ. τὸ δῶρον</span>, “a oferta”, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Tm 4.5</a> (AcThom 79 [Aa II/2, 194, 11] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὴν προσφορὰν ἁ.\" data-meanings=\"consagrar a oferta\">τὴν προσφορὰν ἁ.</span>); de coisas profanas, <strong>tornar santo pelo contato com algo santo</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. τὸν χρυσόν\" data-meanings=\"santificar o ouro\">ἁ. τὸν χρυσόν</span>, o ouro no templo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23.17</a>.\n<span class=\"sense-number\">2.</span> <strong>Incluir uma pessoa no círculo íntimo daquilo que é santo</strong>, nas associações cultuais e morais do termo: <strong>consagrar, dedicar, santificar</strong> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.28.41\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 28.41</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.33.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 33.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.45.4\" target=\"_blank\" rel=\"noopener noreferrer\">45.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ZEP.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Sf 1.7</a>). Assim dos cristãos, consagrados pelo batismo (compare Orígenes, <em>C. Cels.</em> 8, 33, 26, sobre a Eucaristia: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄρτους ἐσθίομεν, σῶμα γενομένους … ἁγιάζον τοὺς μετὰ ὑγιοῦς προθέσεως αὐτῷ χρωμένους\" data-meanings=\"comemos pães tornados corpo … que santificam os que deles participam com reta disposição\">ἄρτους ἐσθίομεν, σῶμα γενομένους … ἁγιάζον τοὺς μετὰ ὑγιοῦς προθέσεως αὐτῷ χρωμένους</span>); com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀπολούσασθαι\" data-meanings=\"lavar-se; ser lavado\">ἀπολούσασθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 6.11</a>. Da comunidade cristã ou igreja: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα αὐτὴν ἁγιάσῃ καθαρίσας τῷ λουτρῷ τοῦ ὕδατος\" data-meanings=\"para santificá-la, purificando-a pelo banho da água\">ἵνα αὐτὴν ἁγιάσῃ καθαρίσας τῷ λουτρῷ τοῦ ὕδατος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 5.26</a>; santificar pelo sangue de um sacrifício, isto é, expiar pecados, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.13</a>. De Cristo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα ἁγιάσῃ διὰ τοῦ ἰδίου αἵματος τὸν λαόν\" data-meanings=\"para santificar o povo por meio do seu próprio sangue\">ἵνα ἁγιάσῃ διὰ τοῦ ἰδίου αἵματος τὸν λαόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13.12</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. τὸν λαόν\" data-meanings=\"santificar o povo\">ἁ. τὸν λαόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JOS.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Js 7.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZK.46.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ez 46.20</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λαὸς ἡγιασμένος\" data-meanings=\"povo santificado\">λαὸς ἡγιασμένος</span> PsSol 17, 26; santificação pelo sangue, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.29.21\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 29.21</a>); compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">10.10</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">29</a>; consagrar/santificar pelo contato com o que é santo: incrédulos por um casamento cristão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 7.14</a>. Por isso os cristãos são <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡγιασμένοι\" data-meanings=\"santificados\">ἡγιασμένοι</span> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.33.3\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 33.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.17.19\" target=\"_blank\" rel=\"noopener noreferrer\">4 Mc 17.19</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.32\" target=\"_blank\" rel=\"noopener noreferrer\">At 20.32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.18\" target=\"_blank\" rel=\"noopener noreferrer\">26.18</a>; IEph 2:2; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ. ἐν Χριστῷ Ἰησοῦ\" data-meanings=\"santificados em Cristo Jesus\">ἡ. ἐν Χριστῷ Ἰησοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 1.2</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ. ἐν ἀληθείᾳ\" data-meanings=\"santificados na verdade\">ἡ. ἐν ἀληθείᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17.19b</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.45.4\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 45.4</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν πίστει\" data-meanings=\"em fidelidade; em fé\">ἐν πίστει</span>); dos cristãos gentios <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν πνεύματι ἁγίῳ\" data-meanings=\"no Espírito Santo\">ἐν πνεύματι ἁγίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.16</a>; a igreja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιασθεῖσα = ἁγία\" data-meanings=\"santificada = santa\">ἁγιασθεῖσα = ἁγία</span> D 10:5; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κλητοὶ ἡ.\" data-meanings=\"chamados e santificados\">κλητοὶ ἡ.</span> 1 Cl ins.; de um indivíduo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"σκεῦος ἡγιασμένον\" data-meanings=\"vaso santificado\">σκεῦος ἡγιασμένον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Tm 2.21</a>; Paulo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡγιασμένος\" data-meanings=\"santificado\">ἡγιασμένος</span> IEph 12:2. Deus consagra os seus, inclusive Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10.36</a> (veja Hdb.³ ad loc.), e os cristãos (compare escólio a Apollon. Rhod. 3, 62 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐλεήσας αὐτὸν ὁ Ζεὺς ἁγνίζει\" data-meanings=\"Zeus, tendo compaixão dele, purifica-o; absolve-o\">ἐλεήσας αὐτὸν ὁ Ζεὺς ἁγνίζει</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">17.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 5.23</a>; estes últimos por meio de Cristo, 1 Cl 59:3. De Jesus: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑπὲρ αὐτῶν (ἐγὼ) ἁγιάζω ἑμαυτόν\" data-meanings=\"por eles eu me consagro\">ὑπὲρ αὐτῶν (ἐγὼ) ἁγιάζω ἑμαυτόν</span>, “dedico-me por eles” (os discípulos), como oferta, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.17.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 17.19a</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ.\" data-meanings=\"consagrar\">ἁ.</span> de uma oferta: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 13.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 15.19</a>).\n<span class=\"sense-number\">3.</span> <strong>Tratar como santo, reverenciar</strong>, de pessoas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κύριον δὲ τὸν Χριστὸν ἁγιάσατε\" data-meanings=\"santificai/reverenciai Cristo como Senhor\">κύριον δὲ τὸν Χριστὸν ἁγιάσατε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pe 3.15</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Is 8.13</a>); de coisas: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιασθήτω τὸ ὄνομά σου\" data-meanings=\"seja santificado o teu nome\">ἁγιασθήτω τὸ ὄνομά σου</span>, “seja o teu nome tido em reverência” (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.29.23\" target=\"_blank\" rel=\"noopener noreferrer\">Is 29.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EZK.36.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ez 36.23</a>; Ps.-Clem., <em>Hom.</em> 13, 4; também gnóstico <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιασθήτω τὸ θέλημά σου\" data-meanings=\"seja santificada a tua vontade\">ἁγιασθήτω τὸ θέλημά σου</span> PPrinc 107, 14; PGM 4, 1191 s. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ὄνομα τὸ ἅγιον τὸ καθηγιασμένον ὑπὸ τ. ἀγγέλων πάντων\" data-meanings=\"o nome santo, santificado por todos os anjos\">τὸ ὄνομα τὸ ἅγιον τὸ καθηγιασμένον ὑπὸ τ. ἀγγέλων πάντων</span>; 1, 206) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.2</a>; D 8:2 (A. Fridrichsen, “Geheiligt werde dein Name”, TT 8, 1917, 1–16; L. Brun, <em>Harnack Festschr.</em> 1921, 22–31; R. Asting, <em>D. Heiligkeit im Urchristentum</em> 1930, 75–85, com bibliografia). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ σάββατον\" data-meanings=\"o sábado\">τὸ σάββατον</span> B 15:1, 3, 6 s. (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 20.8–11</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁγιασθῆναι\" data-meanings=\"ser santificado; manter-se santo\">ἁγιασθῆναι</span>, <strong>manter-se santo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 22.11</a>.\n<span class=\"sense-number\">4.</span> <strong>Eliminar aquilo que é incompatível com a santidade, purificar</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/NUM.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Nm 6.11</a> e outros): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁ. ἀπὸ πάσης πονηρίας καὶ ἀπὸ πάσης σκολιότητος\" data-meanings=\"purificar de toda maldade e de toda perversidade\">ἁ. ἀπὸ πάσης πονηρίας καὶ ἀπὸ πάσης σκολιότητος</span> Hv 3, 9, 1. Este sentido é provavelmente também o de passagens como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Co 1.2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ts 5.23</a>. — V.l. por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠγαπημένη\" data-meanings=\"amada\">ἠγαπημένη</span> IRo ins. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar; temer religiosamente\">ἅζομαι</span>. M-M. TW.\n</p></section>\n</article><article id=\"entry-hagiasma-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁγίασμα</h1><div class=\"entry-meta\"><span class=\"greek\">ατος, τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hagíasma⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"> (Quase exclusivamente bíblico e cristão, mas também Fílon, <em>Plant.</em> 50; PGM 4, 522.) <strong>Espaço separado para devoção, santuário</strong> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Mc 1.21</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.1.36\" target=\"_blank\" rel=\"noopener noreferrer\">36 ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">5.1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.36.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eclo 36.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.49.6\" target=\"_blank\" rel=\"noopener noreferrer\">49.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.50.11\" target=\"_blank\" rel=\"noopener noreferrer\">50.11</a>; TestDan 5:9. “Santidade”: En 12:4; PsSol): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ δεξιὰ μέρη τοῦ ἁ.\" data-meanings=\"as partes à direita do santuário\">τὰ δεξιὰ μέρη τοῦ ἁ.</span> Hv 3, 2, 1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐποίησεν ἁ. ἐν τῷ κοιτῶνι αὐτῆς\" data-meanings=\"fez um lugar consagrado em seu quarto\">ἐποίησεν ἁ. ἐν τῷ κοιτῶνι αὐτῆς</span> (Ana), “dedicou um lugar para oração no quarto de Maria”, GJs 6:1; compare 6:3; 8:2. — De uma estrutura no templo onde se situava o altar, 24:2. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅζομαι\" data-meanings=\"reverenciar\">ἅζομαι</span>. TW.\n</p></section>\n</article>"};
